import re
from typing import Optional, Tuple


def parse_iso8601(date_string: str) -> Optional[Tuple[int, int, int]]:
    """
    Parse an ISO 8601 date string (YYYY-MM-DD) and return a tuple (year, month, day).

    Supports:
    - YYYY-MM-DD format
    - Optional leading/trailing whitespace

    Returns None if the string is invalid.
    """
    if not isinstance(date_string, str):
        return None

    date_string = date_string.strip()

    # Match YYYY-MM-DD pattern
    match = re.match(r'^(\d{4})-(\d{2})-(\d{2})$', date_string)
    if not match:
        return None

    year = int(match.group(1))
    month = int(match.group(2))
    day = int(match.group(3))

    # Validate ranges
    if year < 1 or year > 9999:
        return None
    if month < 1 or month > 12:
        return None
    if day < 1 or day > 31:
        return None

    # Validate day based on month
    days_in_month = {
        1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
    }

    # Handle leap years for February
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            days_in_month[2] = 29
        else:
            days_in_month[2] = 28

    if day > days_in_month[month]:
        return None

    return (year, month, day)


